//! Rust guest interface for Dekopon provider components.
//!
//! Provider authors implement [`Provider`] using ordinary domain types. [`export_provider!`]
//! supplies the JSON-over-WIT adapter required by `dekopon-provider-host`.

#![forbid(unsafe_code)]

use std::fmt;

pub use dekopon_capability::{EffectKind, Idempotency};
pub use dekopon_core::{CapabilityId, ProviderId, RiskLevel};
use serde::{Deserialize, Serialize};
use serde_json::Value;

/// The component WIT contract generated by this SDK.
pub const PROVIDER_WIT: &str = include_str!("../wit/provider.wit");

/// Version of the component manifest returned by a provider.
#[derive(Clone, Copy, Debug, Deserialize, Eq, PartialEq, Serialize)]
pub enum ProviderApiVersion {
    /// Initial experimental provider contract.
    #[serde(rename = "dekopon.dev/provider/v1alpha1")]
    V1Alpha1,
}

/// Manifest returned by a provider component.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ProviderManifest {
    /// Provider manifest API version.
    pub api_version: ProviderApiVersion,
    /// Stable provider identity.
    pub id: ProviderId,
    /// Concise operator-facing description.
    pub description: String,
    /// Read-only capabilities implemented by this component.
    pub capabilities: Vec<ProviderCapability>,
}

/// One prompt-visible capability exported by a provider component.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ProviderCapability {
    /// Stable capability identity.
    pub id: CapabilityId,
    /// Concise model- and operator-facing description.
    pub description: String,
    /// Effect classification. Immediate mode accepts only [`EffectKind::ReadOnly`].
    pub effect: EffectKind,
    /// Coarse risk classification available to callers.
    pub risk: RiskLevel,
    /// Declared retry behavior.
    pub idempotency: Idempotency,
    /// Object-shaped JSON Schema supplied to a model as function parameters.
    pub input_schema: Value,
}

/// Rust implementation contract for a provider component.
pub trait Provider {
    /// Describes the provider and its prompt-visible capabilities.
    fn manifest() -> ProviderManifest;

    /// Executes one capability against syntactically decoded, otherwise untrusted JSON input.
    ///
    /// The immediate host supplies no ambient I/O. This function should be deterministic unless
    /// an eventual host interface explicitly provides a bounded source of nondeterminism.
    fn invoke(capability: &CapabilityId, input: Value) -> Result<Value, ProviderError>;
}

/// Provider-declared invocation failure.
#[derive(Clone, Debug, Eq, PartialEq)]
pub struct ProviderError {
    code: String,
    message: String,
}

impl ProviderError {
    /// Creates a provider error with a stable machine code and bounded human message.
    #[must_use]
    pub fn new(code: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            code: code.into(),
            message: message.into(),
        }
    }

    /// Returns the machine-readable code.
    #[must_use]
    pub fn code(&self) -> &str {
        &self.code
    }

    /// Returns the human-readable message.
    #[must_use]
    pub fn message(&self) -> &str {
        &self.message
    }
}

impl fmt::Display for ProviderError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(formatter, "{}: {}", self.code, self.message)
    }
}

impl std::error::Error for ProviderError {}

/// JSON response returned across the WIT boundary.
#[derive(Clone, Debug, Deserialize, PartialEq, Serialize)]
#[serde(tag = "outcome", rename_all = "camelCase", deny_unknown_fields)]
pub enum ComponentResponse {
    /// Provider execution completed and returned JSON output.
    Succeeded {
        /// Capability-specific result.
        output: Value,
    },
    /// Provider rejected or failed the operation without trapping.
    Failed {
        /// Stable failure detail.
        error: ComponentFailure,
    },
}

/// Serializable provider failure carried by [`ComponentResponse::Failed`].
#[derive(Clone, Debug, Deserialize, Eq, PartialEq, Serialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ComponentFailure {
    /// Stable provider-specific code.
    pub code: String,
    /// Bounded human-readable detail.
    pub message: String,
}

#[doc(hidden)]
pub mod __wit {
    wit_bindgen::generate!({
        path: "wit",
        world: "provider",
        pub_export_macro: true,
    });
}

#[doc(hidden)]
pub fn __describe<P: Provider>() -> String {
    serde_json::to_string(&P::manifest()).unwrap_or_else(|_error| {
        r#"{"apiVersion":"dekopon.dev/provider/v1alpha1","id":"invalid","description":"","capabilities":[]}"#.to_owned()
    })
}

#[doc(hidden)]
pub fn __invoke<P: Provider>(capability: String, input_json: String) -> String {
    let response = match capability.parse::<CapabilityId>() {
        Ok(capability) => match serde_json::from_str::<Value>(&input_json) {
            Ok(input) => match P::invoke(&capability, input) {
                Ok(output) => ComponentResponse::Succeeded { output },
                Err(error) => ComponentResponse::Failed {
                    error: ComponentFailure {
                        code: error.code,
                        message: error.message,
                    },
                },
            },
            Err(error) => ComponentResponse::Failed {
                error: ComponentFailure {
                    code: "invalid-input".to_owned(),
                    message: error.to_string(),
                },
            },
        },
        Err(error) => ComponentResponse::Failed {
            error: ComponentFailure {
                code: "invalid-capability".to_owned(),
                message: error.to_string(),
            },
        },
    };

    serde_json::to_string(&response).unwrap_or_else(|_error| {
        r#"{"outcome":"failed","error":{"code":"serialization-failed","message":"provider response could not be serialized"}}"#.to_owned()
    })
}

/// Exports a Rust [`Provider`] implementation as the import-free Dekopon WIT world.
///
/// Provider crates with additional imports use [`export_provider_with_bindings!`] instead.
#[macro_export]
macro_rules! export_provider {
    ($provider:ty) => {
        struct __DekoponProviderComponent;

        impl $crate::__wit::Guest for __DekoponProviderComponent {
            fn describe() -> ::std::string::String {
                $crate::__describe::<$provider>()
            }

            fn invoke(
                capability: ::std::string::String,
                input_json: ::std::string::String,
            ) -> ::std::string::String {
                $crate::__invoke::<$provider>(capability, input_json)
            }
        }

        $crate::__wit::export!(
            __DekoponProviderComponent with_types_in $crate::__wit
        );
    };
}

/// Exports a Rust [`Provider`] implementation through caller-generated world bindings.
///
/// The bindings module must be an identifier that describes a world with the same root `describe`
/// and `invoke` exports. It may add explicitly versioned imports such as
/// `dekopon:http/client@1.0.0`. Imports remain structural requirements; only a broker host can
/// grant and implement them.
#[macro_export]
macro_rules! export_provider_with_bindings {
    ($provider:ty, $bindings:ident) => {
        struct __DekoponProviderComponent;

        impl $bindings::Guest for __DekoponProviderComponent {
            fn describe() -> ::std::string::String {
                $crate::__describe::<$provider>()
            }

            fn invoke(
                capability: ::std::string::String,
                input_json: ::std::string::String,
            ) -> ::std::string::String {
                $crate::__invoke::<$provider>(capability, input_json)
            }
        }

        $bindings::export!(
            __DekoponProviderComponent with_types_in $bindings
        );
    };
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::{
        __describe, __invoke, CapabilityId, ComponentResponse, EffectKind, Idempotency, Provider,
        ProviderApiVersion, ProviderCapability, ProviderError, ProviderManifest, RiskLevel,
    };

    struct Echo;

    impl Provider for Echo {
        fn manifest() -> ProviderManifest {
            ProviderManifest {
                api_version: ProviderApiVersion::V1Alpha1,
                id: "echo".parse().expect("valid provider fixture"),
                description: "Echoes input".to_owned(),
                capabilities: vec![ProviderCapability {
                    id: "echo.echo".parse().expect("valid capability fixture"),
                    description: "Echoes input".to_owned(),
                    effect: EffectKind::ReadOnly,
                    risk: RiskLevel::Low,
                    idempotency: Idempotency::Idempotent,
                    input_schema: json!({"type": "object"}),
                }],
            }
        }

        fn invoke(
            capability: &CapabilityId,
            input: serde_json::Value,
        ) -> Result<serde_json::Value, ProviderError> {
            if capability.as_str() == "echo.echo" {
                Ok(input)
            } else {
                Err(ProviderError::new("unsupported", capability.to_string()))
            }
        }
    }

    #[test]
    fn adapter_serializes_the_typed_manifest() {
        let manifest: ProviderManifest =
            serde_json::from_str(&__describe::<Echo>()).expect("manifest parses");
        assert_eq!(manifest.id.as_str(), "echo");
    }

    #[test]
    fn adapter_invokes_rust_provider_implementations() {
        let response: ComponentResponse = serde_json::from_str(&__invoke::<Echo>(
            "echo.echo".to_owned(),
            r#"{"message":"hello"}"#.to_owned(),
        ))
        .expect("response parses");

        assert_eq!(
            response,
            ComponentResponse::Succeeded {
                output: json!({"message": "hello"})
            }
        );
    }

    #[test]
    fn adapter_turns_invalid_identifiers_into_failures() {
        let response: ComponentResponse =
            serde_json::from_str(&__invoke::<Echo>("Not Valid".to_owned(), "{}".to_owned()))
                .expect("response parses");

        assert!(matches!(response, ComponentResponse::Failed { .. }));
    }
}
